// UTA — Go example: verify a credential via public HTTP API.\n// Repo: https://github.com/alicelabs-llc/universal-trust-adapter\npackage main\n\nimport (\n\t\"bytes\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"os\"\n)\n\ntype VerifyRequest struct {\n\tCard string `json:\"card\"`\n}\n\ntype VerifyResponse struct {\n\tDecision       string `json:\"decision\"`\n\tDetectedFormat string `json:\"detected_format\"`\n\tIssuer         string `json:\"issuer\"`\n\tFailedStage    string `json:\"failed_stage\"`\n}\n\nfunc main() {\n\tif len(os.Args) < 2 { fmt.Println(\"Usage: verify <card-string>\"); os.Exit(1) }\n\tcard := os.Args[1]\n\tpayload, _ := json.Marshal(VerifyRequest{Card: card})\n\tresp, err := http.Post(\n\t\t\"https://www.marketnow.site/api/trust?action=verify\",\n\t\t\"application/json\",\n\t\tbytes.NewReader(payload),\n\t)\n\tif err != nil { panic(err) }\n\tdefer resp.Body.Close()\n\tbody, _ := io.ReadAll(resp.Body)\n\tvar v VerifyResponse\n\tjson.Unmarshal(body, &v)\n\tfmt.Printf(\"Decision:   %s\\n\", v.Decision)\n\tfmt.Printf(\"Format:     %s\\n\", v.DetectedFormat)\n\tfmt.Printf(\"Issuer:     %s\\n\", v.Issuer)\n}\n